Object.assign(window.SIM_ASSETS.shaders, {"clickShader.frag": "#version 300 es \n\nprecision highp float ;\nprecision highp int ;\n\nuniform sampler2D   in_txt ;\nuniform sampler2D\tin_itxt;\t\t//* Added\nuniform vec2        clickPosition ;\nuniform vec2\t\tclickShiftPosition;\nuniform float       clickRadius ;\nuniform bool \t\tshiftClick ;\nuniform bool        clearBlocks ;      //* Website: removes every block\n\nin vec2 pixPos ;\n\nlayout (location =0) out vec4 out_txt ;\nlayout (location =1) out vec4 out_itxt ;\n\nvoid main(){\n    \n    \n    vec4 txt  = texture(in_txt, pixPos) ;\t\t\n    vec4 itxt = texture(in_itxt, pixPos);\t\t//* Added\n\n    if (clearBlocks){\n        itxt.z = 1.;\n    }else if (shiftClick){\n    \tif ( length(pixPos-clickShiftPosition)<clickRadius){ //* We cannot check the equality of two foats\n    \t\titxt.z = 0.;\t\n    \t}\t\t\t\t\t\t//* This it the only way\n    }else{\n    \tif ( length(pixPos-clickPosition)<clickRadius){\n        \ttxt.r = 0.98 ;\n    \t}\n    }\n    \n\n    \n\n    out_txt = txt ;\n    out_itxt = itxt;\n}\n", "compShader.frag": "#version 300 es\nprecision highp float ;\nprecision highp int ;\n\nuniform sampler2D   in_txt ;\nuniform sampler2D   in_itxt ;\nlayout (location =0) out float out_txt ; // output color of the shader\n\nin vec2 cc ;\n\n\nuniform float radius, threshold, Lx;\n\nvoid main() {\n    vec2 size   = vec2(textureSize(in_txt,0)) ; //size of texture\n    vec2 ii     = vec2(1.,0.)/size ; // Unit vector in x  //size of pixel\n    vec2 jj     = vec2(0.,1.)/size ; // .............. y\n\n    float dx = Lx/size.x ;\n    float dy = dx ;\n\n    vec4  C = texture(in_txt, cc) ;\n    vec2  pert = texture(in_itxt, cc).xy ;\n    float ifBlock = texture(in_itxt, cc).z; //*--> gives me the block condition\n    vec2  cellCoord = cc*Lx + pert ;\n    //C(Voltate, ..., xrand, y.rand)\n    \n    if(ifBlock == 0.){   //* If the pixel is part of the block\n        C.r = -1.;\n    }else{\n        if(C.r < 0.05){\n            float aliveNeighbors = 0.;\n            float deadNeighbors = 0.;\n\n            int m = int(round(radius/dx)) ;\n            int n = int(round(radius/dy)) ;\n            for (int i=-m; i<(m+1) ;i++){\n                for (int j=-n; j<(n+1); j++ ){\n\n                     \n\n                    vec2 currPos =  cc+float(i)*ii+float(j)*jj ;\n                    float reachBlock = texture(in_itxt, currPos).z;\n                        if (reachBlock == 1.){      //* No block\n                            float voltage = texture(in_txt,currPos).r ; //texture\n                            pert = texture(in_itxt,currPos).xy ;\n\n                            vec2 compCellCoord= currPos*vec2(Lx,Lx) + pert ;//physical\n\n                            float distance = length(cellCoord-compCellCoord) ;\n                            if(distance<radius){\n                                if ( (voltage >0.7) && (voltage<0.99) ){\n                                    aliveNeighbors+=1.;\n                                }else{\n                                    deadNeighbors+=1.;\n                                }\n                            }\n                        } else if (reachBlock == 0.) {\n                            currPos = cc+float(i)*ii*(-1.)+float(j)*jj*(-1.) ;  //* mirroring\n                            float voltage = texture(in_txt,currPos).r ; //texture\n                            pert = texture(in_itxt,currPos).xy ;\n\n                            vec2 compCellCoord= currPos*vec2(Lx,Lx) + pert ;//physical\n\n                            float distance = length(cellCoord-compCellCoord) ;\n                            if(distance<radius){\n                                if ( (voltage >0.7) && (voltage<0.99) ){\n                                    aliveNeighbors+=1.;\n                                }else{\n                                    deadNeighbors+=1.;\n                                }\n                            }\n                        }\n                    \n                }\n            }\n                \n            if ((aliveNeighbors/deadNeighbors)>threshold){\n                C.r = C.r + 0.95;\n            }else{\n                C.r = 0.;\n            }\n        }else{ \n        C.r = C.r - 0.051;\n        }\n    }\n    \n\n    out_txt = C.r ;\n\n\n    return ;\n}\n", "initShader.frag": "#version 300 es\n\nprecision highp float ;\nprecision highp int ;\n\nin vec2 cc ;\n\nlayout (location =0) out float o_col_0 ; // fragment color set 0\nlayout (location =1) out float o_col_1 ; // fragment color set 1\n\nvoid main(){\n    float red = 0. ;\n\n    o_col_0 = red ;\n    o_col_1 = red ;\n    return ;\n}\n"});
